MEASURED_TASK_NAMES = ['Plaquettes de frein', 'Pneus']


def mark_measured_tasks(apps, schema_editor):
    TaskCatalog = apps.get_model('garage', 'TaskCatalog')
    TaskCatalog.objects.filter(name__in=MEASURED_TASK_NAMES, is_wear_task=True).update(measured_in_inspection=True)


def delete_obsolete_permissions(apps, schema_editor):
    """manage_inspection passe de MaintenanceConfig à InspectionSheet : create_permissions ne supprime pas
    l'ancienne ligne, et _setup_garage_groups indexe par codename (risque de réassigner l'ancienne)."""
    Permission = apps.get_model('auth', 'Permission')
    Permission.objects.filter(
        content_type__app_label='garage', content_type__model='maintenanceconfig', codename='manage_inspection',
    ).delete()
    Permission.objects.filter(
        content_type__app_label='garage', content_type__model='vehicletaskrecord',
    ).delete()


